 const persist=(next:any,urgent=false)=>{const today=new Date().toISOString().slice(0,10);const base=pendingProgress.current||{xp,completedMissions:completed,completedContent,nickname,avatar,mistakes,correctAnswers,answerCount,activityDays,sectionStats,dailyAnswers,dailyAnswerDate,dailyClaimDate,leaderboardVisible};const days=Array.from(new Set([...(next.activityDays??base.activityDays??[]),today])).slice(-60);const data={...base,...next,activityDays:days};pendingProgress.current=data;localStorage.setItem('meway-progress',JSON.stringify(data));setActivityDays(days);if(discordAuth.accessToken){if(urgent){flushProgress();return}if(progressTimer.current)window.clearTimeout(progressTimer.current);progressTimer.current=window.setTimeout(()=>flushProgress(),20000)}}
 useEffect(()=>{const flush=()=>flushProgress(true);const hidden=()=>{if(document.visibilityState==='hidden')flush()};window.addEventListener('pagehide',flush);document.addEventListener('visibilitychange',hidden);return()=>{window.removeEventListener('pagehide',flush);document.removeEventListener('visibilitychange',hidden);flush()}},[discordAuth.accessToken])
 useEffect(()=>{if(discordAuth.accessToken)return;try{const d=JSON.parse(localStorage.getItem('meway-progress')||'{}');if(d.xp)setXp(d.xp);if(d.completedMissions)setCompleted(d.completedMissions);if(d.completedContent)setCompletedContent(d.completedContent);if(d.nickname)setNickname(d.nickname);if(d.avatar)setAvatar(d.avatar);if(d.mistakes)setMistakes(d.mistakes);if(d.correctAnswers)setCorrectAnswers(d.correctAnswers);if(d.answerCount)setAnswerCount(d.answerCount);if(d.activityDays)setActivityDays(d.activityDays);if(d.sectionStats)setSectionStats(d.sectionStats);if(d.dailyAnswers)setDailyAnswers(d.dailyAnswers);if(d.dailyAnswerDate)setDailyAnswerDate(d.dailyAnswerDate);if(d.dailyClaimDate)setDailyClaimDate(d.dailyClaimDate);setLeaderboardVisible(d.leaderboardVisible!==false)}catch{}},[discordAuth.accessToken])
 const recordAnswer=(ok:boolean,topic='Общее')=>{const ac=answerCount+1,ca=correctAnswers+(ok?1:0),mi=mistakes+(ok?0:1);const prev=sectionStats[topic]||{total:0,correct:0};const ss={...sectionStats,[topic]:{total:prev.total+1,correct:prev.correct+(ok?1:0)}};const today=new Date().toISOString().slice(0,10),da=dailyAnswerDate===today?dailyAnswers+1:1;setAnswerCount(ac);setCorrectAnswers(ca);setMistakes(mi);setSectionStats(ss);setDailyAnswers(da);setDailyAnswerDate(today);persist({answerCount:ac,correctAnswers:ca,mistakes:mi,sectionStats:ss,dailyAnswers:da,dailyAnswerDate:today})};const recordMistake=()=>recordAnswer(false)
 const completeMission=(m:Mission)=>{if(completed.includes(m.id))return;const c=[...completed,m.id],nx=xp+m.xp;setCompleted(c);setXp(nx);persist({xp:nx,completedMissions:c},true)}
 const completeContent=(x:Content)=>{if(completedContent.includes(x.id))return;const c=[...completedContent,x.id],nx=xp+(x.xp||0);setCompletedContent(c);setXp(nx);persist({xp:nx,completedContent:c},true)}
 const updateProfile=(n:string,a:string)=>{setNickname(n);setAvatar(a);persist({nickname:n,avatar:a})}
